import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useTheme } from '../context/ThemeContext';
import { isAuthenticated } from '../util/auth';
import ProductCard from '../components/ProductCard';

const Home = () => {
  const [featuredProducts, setFeaturedProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [currentSlide, setCurrentSlide] = useState(0);
  const [wishlist, setWishlist] = useState([]);
  const { isDarkMode } = useTheme();

  // Mock data for now
  const mockProducts = [
    {
      _id: '1',
      name: 'Fresh Milk',
      description: 'Pure and fresh milk from local farms',
      price: 45,
      originalPrice: 50,
      image: 'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=300&h=200&fit=crop',
      discount: 10,
      rating: 4.5,
      category: 'milk'
    },
    {
      _id: '2',
      name: 'Organic Butter',
      description: 'Premium organic butter with rich taste',
      price: 120,
      originalPrice: 150,
      image: 'https://images.unsplash.com/photo-1586201375765-552d5e6c40a9?w=300&h=200&fit=crop',
      discount: 20,
      rating: 4.8,
      category: 'butter'
    },
    {
      _id: '3',
      name: 'Farm Cheese',
      description: 'Artisanal cheese from traditional farms',
      price: 200,
      originalPrice: 250,
      image: 'https://images.unsplash.com/photo-1483680537829-3c291ee3b4c6?w=300&h=200&fit=crop',
      discount: 20,
      rating: 4.7,
      category: 'cheese'
    },
    {
      _id: '4',
      name: 'Fresh Cream',
      description: 'Rich and creamy fresh cream',
      price: 80,
      originalPrice: 100,
      image: 'https://images.unsplash.com/photo-1588337238144-364c9c5a6bee?w=300&h=200&fit=crop',
      discount: 20,
      rating: 4.6,
      category: 'cream'
    }
  ];

  const mockCategories = ['milk', 'butter', 'cheese', 'cream', 'curd', 'ghee', 'lassi', 'paneer', 'yogurt', 'buttermilk'];

  useEffect(() => {
    fetchData();
    
    // Auto-rotate slides
    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % 3);
    }, 4000);
    
    return () => clearInterval(interval);
  }, []);

  const fetchData = async () => {
    try {
      setLoading(true);
      // Using mock data for now
      setTimeout(() => {
        setFeaturedProducts(mockProducts);
        setCategories(mockCategories);
        setLoading(false);
      }, 1000);
    } catch (error) {
      console.error('Error fetching data:', error);
      setLoading(false);
    }
  };

  const userAuthenticated = isAuthenticated();

  // Add to cart functionality
  const handleAddToCart = (product) => {
    if (!userAuthenticated) {
      // Redirect to login if not authenticated
      window.location.href = '/login';
      return;
    }
    
    // Simple cart functionality for now
    const cart = JSON.parse(localStorage.getItem('cart') || '[]');
    const existingItem = cart.find(item => item._id === product._id);
    
    if (existingItem) {
      existingItem.quantity += 1;
    } else {
      cart.push({
        ...product,
        quantity: 1
      });
    }
    
    localStorage.setItem('cart', JSON.stringify(cart));
    
    // Show success message
    alert('Product added to cart!');
  };

  // Wishlist functionality
  const toggleWishlist = (productId) => {
    if (!userAuthenticated) {
      window.location.href = '/login';
      return;
    }
    
    setWishlist(prev => 
      prev.includes(productId) 
        ? prev.filter(id => id !== productId)
        : [...prev, productId]
    );
  };

  const isInWishlist = (productId) => {
    return wishlist.includes(productId);
  };

  return (
    <div className="fade-in">
      {/* Animated Hero Section */}
      <section className="relative min-h-screen flex items-center justify-center overflow-hidden rounded-2xl mb-12">
        {/* Animated Background */}
        <div className="absolute inset-0 bg-gradient-to-br from-blue-600 via-purple-600 to-pink-600">
          <div className="absolute inset-0 bg-black/20"></div>
          
          {/* Floating Product Images */}
          <div className="absolute inset-0">
            <div className="absolute top-10 left-10 w-20 h-20 bg-white/10 backdrop-blur-lg rounded-full flex items-center justify-center animate-float">
              <span className="text-4xl">🥛</span>
            </div>
            <div className="absolute top-20 right-20 w-16 h-16 bg-white/10 backdrop-blur-lg rounded-full flex items-center justify-center animate-float animation-delay-2">
              <span className="text-3xl">🧀</span>
            </div>
            <div className="absolute bottom-20 left-20 w-24 h-24 bg-white/10 backdrop-blur-lg rounded-full flex items-center justify-center animate-float animation-delay-4">
              <span className="text-5xl">🧈</span>
            </div>
            <div className="absolute bottom-10 right-10 w-18 h-18 bg-white/10 backdrop-blur-lg rounded-full flex items-center justify-center animate-float animation-delay-6">
              <span className="text-4xl">🍯</span>
            </div>
            <div className="absolute top-1/2 left-1/3 w-20 h-20 bg-white/10 backdrop-blur-lg rounded-full flex items-center justify-center animate-float animation-delay-8">
              <span className="text-4xl">🍦</span>
            </div>
          </div>
          
          {/* Animated Gradient Overlay */}
          <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-transparent"></div>
        </div>

        {/* Hero Content */}
        <div className="relative z-10 text-center px-4 max-w-6xl mx-auto">
          
          {/* Animated Milk Bottle Logo */}
          <div className="mb-8">
            <div className="inline-block relative">
              <div className="w-24 h-24 relative animate-bounce">
                {/* Glow Effect */}
                <div className="absolute inset-0 bg-white/30 backdrop-blur-xl rounded-3xl animate-pulse"></div>
                
                {/* Main Bottle */}
                <div className="absolute inset-0 bg-white/90 backdrop-blur-xl rounded-3xl flex items-center justify-center transform hover:scale-110 transition-transform duration-500 shadow-2xl">
                  <svg className="w-16 h-16 text-blue-600" fill="currentColor" viewBox="0 0 24 24">
                    <path d="M7 2v2h1v14a4 4 0 004 4h0a4 4 0 004-4V4h1V2H7zm2 2h6v14a2 2 0 01-2 2h0a2 2 0 01-2-2V4z"/>
                    <path d="M9 6h6v2H9z" opacity="0.3"/>
                  </svg>
                </div>
                
                {/* Animated Milk Drops */}
                <div className="absolute -top-2 -right-2 w-4 h-4 bg-blue-400 rounded-full animate-bounce">
                  <div className="w-full h-full bg-blue-500 rounded-full animate-ping"></div>
                </div>
                <div className="absolute -bottom-1 -left-1 w-3 h-3 bg-purple-400 rounded-full animate-pulse"></div>
              </div>
            </div>
          </div>

          {/* Auto-Sliding Text */}
          <div className="mb-8 h-24 overflow-hidden">
            <div className="transition-transform duration-500 ease-in-out" style={{ transform: `translateY(-${currentSlide * 96}px)` }}>
              <div className="h-24 flex items-center justify-center">
                <h1 className="text-4xl md:text-6xl font-bold text-white">
                  Fresh Milk & Dairy Products
                </h1>
              </div>
              <div className="h-24 flex items-center justify-center">
                <h1 className="text-4xl md:text-6xl font-bold text-white">
                  Farm Fresh Quality
                </h1>
              </div>
              <div className="h-24 flex items-center justify-center">
                <h1 className="text-4xl md:text-6xl font-bold text-white">
                  Delivered Daily
                </h1>
              </div>
            </div>
          </div>
          
          <div className="mb-8">
            <p className="text-xl md:text-2xl text-white/90 max-w-2xl mx-auto animate-fade-in">
              Delivering farm-fresh dairy products directly to your doorstep
            </p>
          </div>

          <div className="flex flex-col sm:flex-row gap-4 justify-center mb-12">
            <Link 
              to="/products" 
              className="px-8 py-4 bg-white text-blue-600 rounded-full font-bold text-lg hover:bg-blue-50 transform hover:scale-105 transition-all duration-300 shadow-2xl animate-fade-in animation-delay-2"
            >
              Shop Now
            </Link>
            {!userAuthenticated && (
              <Link 
                to="/register" 
                className="px-8 py-4 border-2 border-white text-white rounded-full font-bold text-lg hover:bg-white hover:text-blue-600 transform hover:scale-105 transition-all duration-300 animate-fade-in animation-delay-4"
              >
                Create Account
              </Link>
            )}
          </div>

          {/* Slide Indicators */}
          <div className="flex justify-center space-x-2">
            {[0, 1, 2].map((index) => (
              <button
                key={index}
                onClick={() => setCurrentSlide(index)}
                className={`w-3 h-3 rounded-full transition-all duration-300 ${
                  currentSlide === index 
                    ? 'bg-white w-8' 
                    : 'bg-white/50 hover:bg-white/70'
                }`}
              />
            ))}
          </div>
        </div>
      </section>

      {/* Modern Categories Section */}
      <section className="mb-16 relative">
        {/* Modern Section Header */}
        <div className="text-center mb-12">
          <div className="inline-block relative">
            <h2 className={`text-4xl md:text-5xl font-bold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
              <span className="bg-gradient-to-r from-primary-600 via-secondary-600 to-primary-600 bg-clip-text text-transparent">
                Shop by Category
              </span>
            </h2>
            {/* Underline Animation */}
            <div className="absolute -bottom-2 left-0 w-full h-1 bg-gradient-to-r from-primary-500 to-secondary-500 rounded-full transform scale-x-0 group-hover:scale-x-100 transition-transform duration-500"></div>
          </div>
          <p className={`text-lg ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} mt-4 max-w-2xl mx-auto`}>
            Explore our wide range of fresh dairy products
          </p>
        </div>

        {/* Modern Grid Layout */}
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-8">
          {categories.map((category) => (
            <Link
              key={category}
              to={`/products?category=${category}`}
              className="group relative block"
            >
              {/* Ultra-Premium Card Container */}
              <div className="relative p-10 text-center bg-gradient-to-br from-white via-gray-50 to-gray-100 dark:from-gray-800 dark:via-gray-900 dark:to-black rounded-[3rem] border-2 border-gray-200/50 dark:border-gray-700/50 hover:border-primary-500 transition-all duration-1000 transform hover:scale-105 hover:shadow-4xl hover:shadow-primary-500/20 overflow-hidden group">
                
                {/* Multi-Layer Animated Background */}
                <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-all duration-1000">
                  {/* Base Gradient */}
                  <div className="absolute inset-0 bg-gradient-to-br from-primary-500/10 via-transparent to-secondary-500/10 animate-gradient-shift"></div>
                  
                  {/* Sliding Light Effect */}
                  <div className="absolute inset-0">
                    <div className="absolute top-0 left-0 w-full h-1/3 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-slide"></div>
                    <div className="absolute top-1/3 left-0 w-full h-1/3 bg-gradient-to-r from-transparent via-primary-200/20 to-transparent animate-slide animation-delay-2"></div>
                    <div className="absolute bottom-0 left-0 w-full h-1/3 bg-gradient-to-r from-transparent via-secondary-200/20 to-transparent animate-slide animation-delay-4"></div>
                  </div>
                  
                                  </div>
                
                {/* Luxury Glow Effect */}
                <div className="absolute inset-0 bg-gradient-to-br from-primary-500/20 via-secondary-500/15 to-primary-500/20 rounded-[3rem] opacity-0 group-hover:opacity-100 transition-all duration-1000 blur-3xl"></div>
                
                {/* Glass Morphism Overlay */}
                <div className="absolute inset-0 bg-gradient-to-tr from-white/10 to-transparent backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-all duration-1000"></div>
                
                {/* Icon Container with Ultra-Advanced Effects */}
                <div className="relative z-10 mb-8">
                  <div className="w-24 h-24 mx-auto relative">
                    {/* Multi-Layer Icon Background */}
                    <div className="absolute inset-0 bg-gradient-to-br from-primary-100 via-white to-secondary-100 dark:from-primary-900 dark:via-gray-800 dark:to-secondary-900 rounded-[2.5rem] flex items-center justify-center transform transition-all duration-1000 group-hover:scale-125 group-hover:rotate-12 shadow-2xl border-2 border-white/50 dark:border-gray-700/50">
                      {/* Inner Glow */}
                      <div className="absolute inset-2 bg-gradient-to-br from-white/50 to-transparent rounded-[2rem]"></div>
                      
                      {/* Icon with Advanced Effects */}
                      <span className="text-5xl transform transition-all duration-700 group-hover:scale-150 group-hover:rotate-180 drop-shadow-2xl relative z-10">
                        {category === 'milk' && '🥛'}
                        {category === 'butter' && '🧈'}
                        {category === 'buttermilk' && '🫙'}
                        {category === 'cheese' && '🧀'}
                        {category === 'cream' && '🍦'}
                        {category === 'curd' && '🥣'}
                        {category === 'ghee' && '🍯'}
                        {category === 'lassi' && '🥤'}
                        {category === 'paneer' && '🧊'}
                        {category === 'yogurt' && '🍶'}
                      </span>
                    </div>
                    
                    {/* Ultra-Advanced Icon Glow */}
                    <div className="absolute inset-0 bg-gradient-to-br from-primary-400/60 via-secondary-400/40 to-primary-400/60 rounded-[2.5rem] opacity-0 group-hover:opacity-100 transition-all duration-1000 blur-2xl"></div>
                    
                                      </div>
                </div>
                
                {/* Ultra-Enhanced Category Name */}
                <div className="relative z-10">
                  <h3 className={`font-black text-2xl capitalize transition-all duration-700 ${isDarkMode ? 'text-white group-hover:text-primary-300' : 'text-gray-800 group-hover:text-primary-600'}`}>
                    {category}
                  </h3>
                  <div className="mt-3 h-1 bg-gradient-to-r from-transparent via-primary-500 to-transparent transform scale-x-0 group-hover:scale-x-100 transition-all duration-700 rounded-full"></div>
                  <div className="mt-2 text-sm font-medium opacity-0 group-hover:opacity-100 transition-opacity duration-700 text-primary-600 dark:text-primary-400">
                    Explore Products →
                  </div>
                </div>
                
                                
                {/* Premium Card Edge Effects */}
                <div className="absolute inset-0 rounded-[3rem] border-2 border-transparent group-hover:border-primary-300/50 transition-all duration-1000"></div>
                <div className="absolute inset-1 rounded-[3rem] border border-transparent group-hover:border-white/30 transition-all duration-1000"></div>
                
                {/* Hover Reveal Effect */}
                <div className="absolute inset-x-0 bottom-0 h-1/3 bg-gradient-to-t from-primary-500/10 to-transparent opacity-0 group-hover:opacity-100 transition-all duration-1000 transform translate-y-full group-hover:translate-y-0"></div>
              </div>
            </Link>
          ))}
        </div>
      </section>

      {/* Modern Featured Products Section */}
      <section className="mb-16">
        {/* Modern Section Header */}
        <div className="text-center mb-12">
          <div className="inline-block relative">
            <h2 className={`text-4xl md:text-5xl font-bold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
              <span className="bg-gradient-to-r from-primary-600 via-secondary-600 to-primary-600 bg-clip-text text-transparent">
                Featured Products
              </span>
            </h2>
            {/* Underline Animation */}
            <div className="absolute -bottom-2 left-0 w-full h-1 bg-gradient-to-r from-primary-500 to-secondary-500 rounded-full transform scale-x-0 group-hover:scale-x-100 transition-transform duration-500"></div>
          </div>
          <p className={`text-lg ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} mt-4 max-w-2xl mx-auto`}>
            Discover our handpicked selection of premium dairy products
          </p>
        </div>
        
        {loading ? (
          <div className="flex justify-center py-16">
            <div className="relative">
              <div className="w-16 h-16 border-4 border-primary-200 border-t-primary-600 rounded-full animate-spin"></div>
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-8 h-8 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-full animate-pulse"></div>
              </div>
            </div>
          </div>
        ) : featuredProducts.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
            {featuredProducts.slice(0, 8).map((product, index) => (
              <div key={product._id} className="group relative">
                {/* Premium Product Card */}
                <div className="relative bg-gradient-to-br from-white via-gray-50 to-gray-100 dark:from-gray-800 dark:via-gray-900 dark:to-black rounded-[2.5rem] border-2 border-gray-200/50 dark:border-gray-700/50 hover:border-primary-500 transition-all duration-1000 transform hover:scale-105 hover:shadow-4xl hover:shadow-primary-500/20 overflow-hidden">
                  
                  {/* Product Image Container */}
                  <div className="relative h-48 overflow-hidden rounded-t-[2.3rem]">
                    <div className="absolute inset-0 bg-gradient-to-br from-primary-500/10 to-secondary-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-1000"></div>
                    <img 
                      src={product.image} 
                      alt={product.name} 
                      className="w-full h-full object-cover transform transition-transform duration-1000 group-hover:scale-110"
                    />
                    
                    {/* Product Badge */}
                    {product.discount && (
                      <div className="absolute top-4 right-4 bg-gradient-to-br from-red-500 to-pink-500 text-white px-3 py-1 rounded-full text-sm font-bold shadow-lg animate-pulse">
                        {product.discount}% OFF
                      </div>
                    )}
                    
                    {/* Wishlist Icon */}
                    <button 
                      onClick={(e) => {
                        e.preventDefault();
                        toggleWishlist(product._id);
                      }}
                      className="absolute top-4 left-4 w-10 h-10 bg-white/90 dark:bg-gray-800/90 backdrop-blur-sm rounded-full flex items-center justify-center shadow-lg hover:scale-110 transition-all duration-300 z-10"
                    >
                      <svg 
                        className={`w-5 h-5 transition-colors duration-300 ${
                          isInWishlist(product._id) 
                            ? 'text-red-500 fill-current' 
                            : 'text-gray-600 dark:text-gray-400'
                        }`}
                        fill="none" 
                        stroke="currentColor" 
                        viewBox="0 0 24 24"
                      >
                        <path 
                          strokeLinecap="round" 
                          strokeLinejoin="round" 
                          strokeWidth={2} 
                          d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" 
                        />
                      </svg>
                    </button>
                  </div>
                  
                  {/* Product Details */}
                  <div className="p-6">
                    <h3 className={`font-bold text-xl mb-2 capitalize transition-colors duration-300 ${isDarkMode ? 'text-white group-hover:text-primary-300' : 'text-gray-800 group-hover:text-primary-600'}`}>
                      {product.name}
                    </h3>
                    
                    <p className={`text-sm mb-4 line-clamp-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
                      {product.description}
                    </p>
                    
                    {/* Price and Rating */}
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center space-x-2">
                        <span className={`text-2xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                          ₹{product.price}
                        </span>
                        {product.originalPrice && (
                          <span className={`text-sm line-through ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`}>
                            ₹{product.originalPrice}
                          </span>
                        )}
                      </div>
                      
                      {/* Rating Stars */}
                      <div className="flex items-center">
                        {[...Array(5)].map((_, i) => (
                          <svg 
                            key={i} 
                            className={`w-4 h-4 ${i < (product.rating || 4) ? 'text-yellow-400' : 'text-gray-300'}`}
                            fill="currentColor" 
                            viewBox="0 0 20 20"
                          >
                            <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
                          </svg>
                        ))}
                      </div>
                    </div>
                    
                    {/* Add to Cart Button */}
                    <button 
                      onClick={() => handleAddToCart(product)}
                      className="w-full bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-bold py-3 rounded-2xl hover:from-primary-600 hover:to-secondary-600 transform transition-all duration-300 hover:scale-105 shadow-lg"
                    >
                      Add to Cart
                    </button>
                  </div>
                  
                  {/* Card Edge Effects */}
                  <div className="absolute inset-0 rounded-[2.5rem] border-2 border-transparent group-hover:border-primary-300/50 transition-all duration-1000"></div>
                  <div className="absolute inset-1 rounded-[2.5rem] border border-transparent group-hover:border-white/30 transition-all duration-1000"></div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-16">
            <div className="inline-block relative mb-8">
              <div className="w-32 h-32 bg-gradient-to-br from-primary-100 to-secondary-100 dark:from-primary-900 dark:to-secondary-900 rounded-[3rem] flex items-center justify-center mx-auto">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-primary-600 dark:text-primary-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" />
                </svg>
              </div>
              {/* Empty State Glow */}
              <div className="absolute inset-0 bg-gradient-to-br from-primary-500/20 to-secondary-500/20 rounded-[3rem] blur-2xl animate-pulse"></div>
            </div>
            <h3 className={`text-3xl font-bold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
              No products yet
            </h3>
            <p className={`text-lg mb-8 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} max-w-md mx-auto`}>
              Check back soon for fresh dairy products!
            </p>
            <Link 
              to="/products" 
              className="inline-flex items-center px-8 py-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-bold rounded-2xl hover:from-primary-600 hover:to-secondary-600 transform transition-all duration-300 hover:scale-105 shadow-xl"
            >
              Browse Products
              <svg className="w-5 h-5 ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
              </svg>
            </Link>
          </div>
        )}
        
        {/* View All Button */}
        <div className="text-center mt-12">
          <Link 
            to="/products" 
            className="inline-flex items-center px-12 py-4 border-2 border-primary-500 text-primary-600 dark:text-primary-400 font-bold rounded-2xl hover:bg-primary-500 hover:text-white transform transition-all duration-300 hover:scale-105"
          >
            View All Products
            <svg className="w-5 h-5 ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 8l4 4m0 0l-4 4m4-4H3" />
            </svg>
          </Link>
        </div>
      </section>

      {/* Features Section */}
      <section className="mb-12">
        <div className="grid md:grid-cols-3 gap-8">
          <div className="card p-6 text-center">
            <div className="w-16 h-16 bg-primary-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-primary-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <h3 className={`text-lg font-semibold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>Fresh Quality</h3>
            <p className={isDarkMode ? 'text-gray-300' : 'text-gray-600'}>100% pure and fresh dairy products sourced from trusted farms</p>
          </div>
          
          <div className="card p-6 text-center">
            <div className="w-16 h-16 bg-primary-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-primary-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <h3 className={`text-lg font-semibold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>Fast Delivery</h3>
            <p className={isDarkMode ? 'text-gray-300' : 'text-gray-600'}>Quick and reliable delivery to ensure product freshness</p>
          </div>
          
          <div className="card p-6 text-center">
            <div className="w-16 h-16 bg-primary-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-primary-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <h3 className={`text-lg font-semibold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>Best Price</h3>
            <p className={isDarkMode ? 'text-gray-300' : 'text-gray-600'}>Competitive prices for premium quality dairy products</p>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Home;
